def countPalindromicWords(digits):
    keys = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl", "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
    n = len(digits)
    ans = 1
    for i in range(n // 2):
        ans *= len(set(keys[digits[i]]) & set(keys[digits[n - 1 - i]]))
    if n % 2:
        ans *= len(keys[digits[n // 2]])
    return ans
